import{_ as r,a0 as o,w as u,s,I as t,x as a,a1 as p,A as i,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"动态壁纸给linux发行版添加活力背景 | LCTT x X-CMD","titleTemplate":false,"description":"动态壁纸给linux发行版添加活力背景 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"动态壁纸给linux发行版添加活力背景 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"动态壁纸给linux发行版添加活力背景 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150527 Animated Wallpaper Adds Live Backgrounds To Linux Distros","title":"动态壁纸给linux发行版添加活力背景","tag":"201507","desc":""},"relativePath":"201507/20150527 Animated Wallpaper Adds Live Backgrounds To Linux Distros.md","filePath":"[post].md"}'),d={name:"201507/20150527 Animated Wallpaper Adds Live Backgrounds To Linux Distros.md"};function m(g,l,x,b,w,f){const e=o("Link");return u(),s("div",null,[l[19]||(l[19]=t("h1",{id:"动态壁纸给linux发行版添加活力背景",tabindex:"-1"},[a("动态壁纸给linux发行版添加活力背景 "),t("a",{class:"header-anchor",href:"#动态壁纸给linux发行版添加活力背景","aria-label":"Permalink to “动态壁纸给linux发行版添加活力背景”"},"​")],-1)),l[20]||(l[20]=t("p",null,[t("strong",null,"我们知道你想拥有一个有格调的ubuntu桌面来炫耀一下 ：）")],-1)),l[21]||(l[21]=t("p",null,[t("img",{src:"http://i.imgur.com/9JIUw5p.gif",alt:"Live Wallpaper"})],-1)),l[22]||(l[22]=t("p",null,[t("em",null,"Live Wallpaper")],-1)),t("p",null,[l[1]||(l[1]=a("在linxu上费一点点劲搭建一个出色的工作环境是很简单的。今天，我们（",-1)),p(e,{href:"http://www.omgubuntu.co.uk/2011/11/5-system-monitoring-tools-for-ubuntu"},{default:i(()=>[...l[0]||(l[0]=[a("重新",-1)])]),_:1}),l[2]||(l[2]=a("）着重来探讨长驻你脑海中那些东西 ：一款自由，开源，能够给你的截图增添光彩的工具。",-1))]),l[23]||(l[23]=n('<p>它叫 <strong>Live Wallpaper</strong> (正如你猜的那样) ，它用由OpenGL驱动的一款动态桌面背景来代替标准的静态桌面背景。</p><p>最好的一点是：在ubuntu上安装它很容易。</p><h3 id="动态壁纸主题" tabindex="-1">动态壁纸主题 <a class="header-anchor" href="#动态壁纸主题" aria-label="Permalink to “动态壁纸主题”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/animated-wallpaper-ubuntu-750x383.jpg" alt=""></p><p>Live Wallpaper 不是此类软件唯一的一款，但它是最好的一款之一。</p><p>它附带很多不同的开箱即用的主题。</p><p>从精细的(‘noise’)到狂热的 (‘nexus’)，包罗万象，甚至有受到Ubuntu Phone欢迎屏幕启发的obligatory锁屏壁纸。</p><ul><li>Circles — 带着‘evolving circle’风格的时钟，灵感来自于Ubuntu Phone</li><li>Galaxy — 支持自定义大小，位置的旋转星系</li><li>Gradient Clock — 放在倾斜面上的polar时钟</li><li>Nexus — 亮色粒子火花穿越屏幕</li><li>Noise — 类似于iOS动态壁纸的Bokeh设计</li><li>Photoslide — 由文件夹（默认为 ~/Photos）内照片构成的动态网格相册</li></ul><p>Live Wallpaper <strong>完全开源</strong>，所以没有什么能够阻挡天马行空的艺术家们用诀窍（当然还有耐心）来创造他们自己的精美主题。</p><h3 id="设置-特点" tabindex="-1">设置 &amp; 特点 <a class="header-anchor" href="#设置-特点" aria-label="Permalink to “设置 &amp; 特点”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/live-wallpaper-gui-settings.jpg" alt=""></p><p>虽然某些主题与其它主题相比有更多的选项，但每款主题都可以通过某些方式来配置或者定制。</p><p>例如，Nexus主题中 (上图所示) 你可以更改脉冲粒子的数量，颜色，大小和出现频率。</p><p>首选项提供了 <strong>通用选项</strong> 适用于所有主题，包括:</p><ul><li>设置登录界面的动态壁纸</li><li>自定义动画背景</li><li>调节 FPS (包括在屏幕上显示FPS)</li><li>指定多显示器的行为</li></ul><p>有如此多的选项，diy适用于你自己的桌面背景是很容易的。</p><h3 id="缺陷" tabindex="-1">缺陷 <a class="header-anchor" href="#缺陷" aria-label="Permalink to “缺陷”">​</a></h3><h4 id="没有桌面图标" tabindex="-1">没有桌面图标 <a class="header-anchor" href="#没有桌面图标" aria-label="Permalink to “没有桌面图标”">​</a></h4><p>Live Wallpaper在运行时，你无法在桌面添加，打开或者是编辑文件和文件夹。</p><p>首选项程序提供了一个选项来让你这样做（只是猜测）。也许是它只能在老版本中使用，在我们的测试中－测试环境为Ununtu 14.10，它不工作。但在测试中发现当把桌面壁纸设置成格式为png的图片文件时，这个选项有用，不需要是透明的png图片文件，只要是png图片文件就行了。</p><h4 id="资源占用" tabindex="-1">资源占用 <a class="header-anchor" href="#资源占用" aria-label="Permalink to “资源占用”">​</a></h4><p>动态壁纸与标准的壁纸相比要消耗更多的系统资源。</p>',22)),t("p",null,[l[4]||(l[4]=a("我们并不是说任何时候都会消耗大量资源，但至少在我们的测试中是这样，所以低配置机器和笔记本用户要谨慎使用这款软件。可以使用 ",-1)),p(e,{href:"http://www.omgubuntu.co.uk/2011/11/5-system-monitoring-tools-for-ubuntu"},{default:i(()=>[...l[3]||(l[3]=[a("系统监视器",-1)])]),_:1}),l[5]||(l[5]=a(" 来追踪CPU 和GPU的负载。",-1))]),l[24]||(l[24]=n(`<h4 id="退出程序" tabindex="-1">退出程序 <a class="header-anchor" href="#退出程序" aria-label="Permalink to “退出程序”">​</a></h4><p>对我来说最大的“bug”绝对是没有“退出”选项。</p><p>当然，动态壁纸可以通过托盘图标和首选项完全退出，那退出托盘图标呢？没办法。只能在终端执行命令‘pkill livewallpaper’。</p><h3 id="怎么在-ubuntu-14-04-lts-上安装-live-wallpaper" tabindex="-1">怎么在 Ubuntu 14.04 LTS+ 上安装 Live Wallpaper <a class="header-anchor" href="#怎么在-ubuntu-14-04-lts-上安装-live-wallpaper" aria-label="Permalink to “怎么在 Ubuntu 14.04 LTS+ 上安装 Live Wallpaper”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/terminal-command-750x146.jpg" alt=""></p><p>要想在Ubuntu 14.04 LTS 和更高版本中安装 Live Wallpaper，你首先需要把官方PPA添加进你的软件源。 最快的方法是在终端中执行下列命令:</p><pre><code>sudo add-apt-repository ppa:fyrmir/livewallpaper-daily

sudo apt-get update &amp;&amp; sudo apt-get install livewallpaper
</code></pre><p>你还需要安装 indicator applet，这样可以方便快速的打开或是关闭动态壁纸，从菜单选择主题，另外图形配置工具可以让你基于你自己的口味来配置每款主题。</p><pre><code>sudo apt-get install livewallpaper-config livewallpaper-indicator
</code></pre><p>所有都安装好之后你就可以通过Unity Dash来启动它和它的首选项工具了。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/05/live-wallpaper-app-launcher.png" alt=""></p><p>让人不爽的是，安装完成后，程序不会自动打开托盘图标，而仅仅将它自己加入自动启动项，所以，快速来个注销 -&gt; 登陆它就会出现啦。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如果你正处在无聊呆板的桌面中，幻想有一个更有活力的生活，不妨试试。另外，告诉我们你想看到什么样的动态壁纸！</p><hr>`,15)),t("p",null,[l[7]||(l[7]=a("via: ",-1)),p(e,{href:"http://www.omgubuntu.co.uk/2015/05/animated-wallpaper-adds-live-backgrounds-to-linux-distros"},{default:i(()=>[...l[6]||(l[6]=[a("http://www.omgubuntu.co.uk/2015/05/animated-wallpaper-adds-live-backgrounds-to-linux-distros",-1)])]),_:1})]),t("p",null,[l[11]||(l[11]=a("作者：",-1)),p(e,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:i(()=>[...l[8]||(l[8]=[a("Joey-Elijah Sneddon",-1)])]),_:1}),l[12]||(l[12]=a(" 译者：",-1)),p(e,{href:"https://github.com/Love-xuan"},{default:i(()=>[...l[9]||(l[9]=[a("Love-xuan",-1)])]),_:1}),l[13]||(l[13]=a(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...l[10]||(l[10]=[a("wxy",-1)])]),_:1})]),t("p",null,[l[16]||(l[16]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...l[14]||(l[14]=[a("LCTT",-1)])]),_:1}),l[17]||(l[17]=a(" 原创翻译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...l[15]||(l[15]=[a("Linux中国",-1)])]),_:1}),l[18]||(l[18]=a(" 荣誉推出",-1))])])}const v=r(d,[["render",m]]);export{L as __pageData,v as default};
